                state.decisions = {
                    d1: 'A',
                    d2: 'A',
                    d3: 'A',
                    d4: 'A',
                    d5: 'A'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;

            var panel = document.getElementById('decisionsPanel');
            if (!panel) return;

            var html = '';
            for (var di = 0; di < round.decisions.length; di++) {
                var dec = round.decisions[di];
                html += '<div class="circularchain-sim-decision-group">';
                html += '<h5>' + (di + 1) + '. ' + dec.label + '</h5>';
                html += '<p>' + dec.description + '</p>';
                for (var oi = 0; oi < dec.options.length; oi++) {
                    var opt = dec.options[oi];
                    var costStr = opt.cost >= 1000000 ? '$' + (opt.cost / 1000000).toFixed(1) + 'M' : '$' + (opt.cost / 1000).toFixed(0) + 'K';
                    if (opt.cost === 0) costStr = '$0';
                    html += '<label><input type="radio" name="' + dec.id + '" value="' + opt.letter + '"';
                    if (opt.letter === 'A') html += ' checked';
                    html += '> <strong>' + opt.letter + ':</strong> ' + opt.label + ' (' + costStr + ')</label>';
                }
                html += '</div>';
            }
            panel.innerHTML = html;

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';
        }

        validateDecisions(decisions) {
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var totalCost = 0;
            for (var di = 0; di < round.decisions.length; di++) {
                var dec = round.decisions[di];
                var selected = document.querySelector('input[name="' + dec.id + '"]:checked');
                if (!selected) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('select_all_warning'), 'warning'
                    );
                    return false;
                }
                var letter = selected.value;
                decisions['d' + (di + 1)] = letter;

                var opt = dec.options.find(function(o) { return o.letter === letter; });
                if (opt) totalCost += opt.cost;
            }

            var remaining = window.mySimulation.state.domainState.capital;
            if (totalCost > remaining) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var ds = state.domainState;

            var roundCost = 0;
            var roundEffects = {
                circularityRate: 0,
                environmentalScore: 0,
                customerSatisfaction: 0,
                supplychainCostPerUnit: 0,
                collectionRate: 0,
                recoveryRate: 0,
                refurbCapacity: 0,
                materialRecoveryRate: 0
            };

            var choiceLabels = [];

            for (var di = 0; di < round.decisions.length; di++) {
                var dec = round.decisions[di];
                var letter = state.decisions['d' + (di + 1)] || 'A';
                var opt = dec.options.find(function(o) { return o.letter === letter; });
                if (opt) {
                    roundCost += opt.cost;
                    for (var key in opt.effects) {
                        if (roundEffects.hasOwnProperty(key)) {
                            roundEffects[key] += opt.effects[key];
                        }
                    }
                    choiceLabels.push(letter);
                }
            }

            ds.capital -= roundCost;
            ds.capitalSpent += roundCost;
            ds.circularityRate = Math.min(100, Math.max(0, ds.circularityRate + roundEffects.circularityRate));
            ds.supplychainCostPerUnit = Math.max(100, ds.supplychainCostPerUnit + roundEffects.supplychainCostPerUnit);
            ds.environmentalScore = Math.min(100, Math.max(0, ds.environmentalScore + roundEffects.environmentalScore));
            ds.customerSatisfaction = Math.min(100, Math.max(0, ds.customerSatisfaction + roundEffects.customerSatisfaction));
            ds.collectionRate = Math.min(100, Math.max(0, ds.collectionRate + roundEffects.collectionRate));
            ds.recoveryRate = Math.min(100, Math.max(0, ds.recoveryRate + roundEffects.recoveryRate));
            ds.refurbCapacity = Math.max(0, ds.refurbCapacity + roundEffects.refurbCapacity);
            ds.materialRecoveryRate = Math.min(100, Math.max(0, ds.materialRecoveryRate + roundEffects.materialRecoveryRate));

            var eventText = '';
            var eventTitle = '';
            if (round.events && round.events.length > 0) {
                var roll = Math.random();
                var cumulative = 0;
                var triggered = null;
                for (var ei = 0; ei < round.events.length; ei++) {
                    cumulative += round.events[ei].probability;
                    if (roll < cumulative) {
                        triggered = round.events[ei];
                        break;
                    }
                }
                if (!triggered) triggered = round.events[round.events.length - 1];

                for (var ekey in triggered.effects) {
                    if (ds.hasOwnProperty(ekey)) {
                        ds[ekey] = Math.min(100, Math.max(0, ds[ekey] + triggered.effects[ekey]));
                    }
                }
                eventTitle = triggered.title;
                eventText = triggered.description;
                ds.eventLog.push({ period: state.currentPeriod, title: eventTitle, description: eventText });
            }

            var circScore = 0;
            if (ds.circularityRate > 70) circScore = 100;
            else if (ds.circularityRate > 55) circScore = 80;
            else if (ds.circularityRate > 40) circScore = 60;
            else if (ds.circularityRate > 30) circScore = 40;
            else circScore = 20;

            var costScore = 0;
            var costChange = ((ds.supplychainCostPerUnit - 185) / 185) * 100;
            if (costChange < -10) costScore = 100;
            else if (costChange < -5) costScore = 85;
            else if (costChange <= 5) costScore = 70;
            else if (costChange <= 15) costScore = 40;
            else costScore = 10;

            var envScore = 0;
            if (ds.environmentalScore > 80) envScore = 100;
            else if (ds.environmentalScore > 60) envScore = 85;
            else if (ds.environmentalScore > 40) envScore = 70;
            else if (ds.environmentalScore > 20) envScore = 40;
            else envScore = 10;

            var csatScore = 0;
            var csatImprove = ((ds.customerSatisfaction - 42) / 42) * 100;
            if (csatImprove > 30) csatScore = 100;
            else if (csatImprove > 15) csatScore = 75;
            else if (csatImprove > 5) csatScore = 50;
            else csatScore = 20;

            // Recovery/collection sub-score: folds in the reverse-logistics KPIs
            // (collectionRate, recoveryRate, refurbCapacity, materialRecoveryRate)
            // which previously accumulated but never affected the outcome.
            var recoveryIndex = Math.round((
                Math.min(100, ds.collectionRate) +
                Math.min(100, ds.recoveryRate) +
                Math.min(100, ds.refurbCapacity) +
                Math.min(100, ds.materialRecoveryRate)
            ) / 4);
            ds.recoveryIndex = recoveryIndex;
            var recoveryScore = recoveryIndex;

            var composite = Math.round((circScore * 0.25) + (costScore * 0.20) + (envScore * 0.20) + (csatScore * 0.15) + (recoveryScore * 0.20));
            ds.compositeScore = composite;

            ds.compositeHistory.push(composite);
            ds.circularityHistory.push(ds.circularityRate);
            ds.costHistory.push(ds.supplychainCostPerUnit);
            ds.envHistory.push(ds.environmentalScore);
            ds.csatHistory.push(ds.customerSatisfaction);
            ds.capitalHistory.push(Math.round(ds.capital / 1000000));

            if (eventText) {
                var eventPanel = document.getElementById('eventPanel');
                var eventTextEl = document.getElementById('eventText');
                if (eventPanel && eventTextEl) {
                    eventPanel.style.display = 'block';
                    eventTextEl.innerHTML = '<strong>' + eventTitle + ':</strong> ' + eventText;
                }
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                choices: choiceLabels.join('/'),
                roundCost: roundCost,
                capitalRemaining: ds.capital,
                circularityRate: ds.circularityRate,
                costPerUnit: ds.supplychainCostPerUnit,
                envScore: ds.environmentalScore,
                satisfaction: ds.customerSatisfaction,
                compositeScore: composite,
                recoveryIndex: recoveryIndex,
                eventTitle: eventTitle || 'None'
            };
        }

