        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var composite = last.results ? last.results.compositeScore : 0;

            var performance = 'Poor';
            if (composite >= 90) performance = 'Leadership';
            else if (composite >= 75) performance = 'Advanced';
            else if (composite >= 60) performance = 'Proficient';
            else if (composite >= 40) performance = 'Developing';

            var insights = [];
            var lastResults = last.results || {};
            if (lastResults.circularityRate > 55) insights.push('Strong circularity rate achieved through strategic investments in reverse logistics and material recovery.');
            if (lastResults.circularityRate <= 30) insights.push('Circularity rate remains low. Consider more aggressive investment in collection and recovery infrastructure.');
            if (lastResults.costPerUnit < 175) insights.push('Supply chain cost optimization successful through circular efficiencies.');
            if (lastResults.costPerUnit > 195) insights.push('Supply chain costs increased. Review cost structure and automation opportunities.');
            if (lastResults.satisfaction > 60) insights.push('Customer satisfaction improved significantly, validating the circular brand strategy.');
            if (lastResults.envScore > 60) insights.push('Environmental impact scores reflect meaningful progress toward sustainability goals.');

            return {
                compositeScore: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.capital < 10000000 && state.currentPeriod < 5)
                return window.mySimulation.t('hint_low_capital');
            if (results.compositeScore < 30)
                return window.mySimulation.t('hint_low_score');
            if (ds.circularityRate < 20 && state.currentPeriod > 2)
                return window.mySimulation.t('hint_low_circularity');
            if (results.compositeScore > 70)
                return window.mySimulation.t('hint_strong');
            return null;
        }

